// Dual-host routing decision for the Cyrus host (cyrus.my). PURE + Edge-safe: middleware.ts calls it, tests pin it.
// The same app serves both hosts; on the Cyrus host only the Cyrus surface exists, everything else is either handed
// to Nxeon (portal pages) or 404s. The marketing landing at "/" is nginx's static page; if "/" reaches the app it
// goes to the studio.
import type { BridgeConfig } from "./config";
import { APP_BASE, CYRUS_APP_PATHS } from "../app/flags";
import { HELP_BASE_INTERNAL, helpPath } from "../help/paths";

export type HostRoute =
  | { kind: "pass" }
  | { kind: "rewrite"; pathname: string }
  | { kind: "redirect"; url: string; status: 302 | 307 }
  | { kind: "notfound" };

const STATIC_RE = /\.(?:png|jpe?g|gif|webp|avif|svg|ico|mp4|webm|woff2?|css|json|txt|glb|gltf|ogg|wav)$/i;
const under = (p: string, prefix: string) => p === prefix || p.startsWith(prefix + "/");

/** Internal tree for Cyrus-host-only pages; 404 on every other host. */
export const CYRUS_HOST_TREE = "/cyrus-host";

/** Auth pages and handlers that exist only on the Cyrus host (public path -> internal path). */
const CYRUS_PAGES: Record<string, string> = {
  "/sign-in": `${CYRUS_HOST_TREE}/sign-in`,
  "/sign-up": `${CYRUS_HOST_TREE}/sign-up`,
  "/auth/nxeon/start": `${CYRUS_HOST_TREE}/auth/start`,
  "/auth/nxeon/callback": `${CYRUS_HOST_TREE}/auth/callback`,
  "/auth/handoff": `${CYRUS_HOST_TREE}/auth/handoff`,
  "/auth/logout": `${CYRUS_HOST_TREE}/auth/logout`,
};

/** APIs the Cyrus screens call (same handlers as on Nxeon). */
const CYRUS_APIS = ["/api/cyrus", "/api/mod-builder", "/api/nxlabs/cyrus"];

export function cyrusHostRoute(a: { pathname: string; search: string; method: string; cfg: BridgeConfig }): HostRoute {
  const p = a.pathname;
  const read = a.method === "GET" || a.method === "HEAD";
  // The internal tree is the rewrite target of the public auth paths (Next may run middleware again on it): on the
  // Cyrus host it is just another name for them. Off the Cyrus host middleware 404s it, and its pages/handlers
  // refuse to render without the marker this middleware alone sets.
  if (under(p, CYRUS_HOST_TREE)) return { kind: "pass" };
  if (p.startsWith("/_next/") || p === "/favicon.ico" || p.startsWith("/.well-known/") || p.startsWith("/vendor/") || STATIC_RE.test(p)) return { kind: "pass" };
  if (read && under(p, HELP_BASE_INTERNAL)) return { kind: "pass" };
  if (CYRUS_APIS.some((x) => under(p, x))) return { kind: "pass" };
  if (under(p, "/dashboard/cyrus")) return { kind: "pass" };
  if (under(p, "/studio")) return { kind: "rewrite", pathname: "/dashboard/cyrus" + p.slice("/studio".length) };
  if (CYRUS_PAGES[p]) return { kind: "rewrite", pathname: CYRUS_PAGES[p] };
  // Customer app (r39): /home, /new, /account, /assets, /projects[/<id>] are the app tree (its pages 404 while CYRUS_CUSTOMER_APP is off).
  const app = appPath(p); if (app) return { kind: "rewrite", pathname: app };
  if (!read) return { kind: "notfound" };
  // Help center (r50): public /help[/<slug>] is the rewrite source for the (cyrus-help) route group; it 404s while CYRUS_CUSTOMER_APP is off.
  const help = helpPath(p); if (help) return { kind: "rewrite", pathname: help };
  if (p === "/") return { kind: "redirect", url: "/studio", status: 302 };
  if (p === "/login") return { kind: "redirect", url: "/sign-in" + a.search, status: 302 };
  if (p === "/register") return { kind: "redirect", url: "/sign-up" + a.search, status: 302 };
  // Portal pages (servers, wallet, billing...) live on Nxeon: hand the visitor over, same path.
  if (under(p, "/dashboard")) return { kind: "redirect", url: a.cfg.nxeonOrigin + p + a.search, status: 302 };
  return { kind: "notfound" };
}

/** Public customer-app path -> internal path (null = not an app path). */
export function appPath(p: string): string | null {
  if (CYRUS_APP_PATHS[p]) return CYRUS_APP_PATHS[p];
  if (p.startsWith("/projects/") && /^\/projects\/[A-Za-z0-9_-]{1,64}$/.test(p)) return APP_BASE + p;
  return null;
}

/** Same-site post-sign-in destination on the Cyrus host: a single-slash path into the Cyrus surface, else /studio. */
export function safeCyrusNext(raw: string | null | undefined): string {
  const s = String(raw ?? "");
  if (!/^\/(?![/\\])[^\s]*$/.test(s) || s.length > 512 || s.includes("\\")) return "/studio";
  const path = s.split(/[?#]/)[0];
  if (under(path, "/studio") || under(path, "/dashboard/cyrus") || path === "/auth/handoff" || appPath(path)) return s;
  return "/studio";
}

// ---------------------------------------------------------------------------
// r51: the secret Cyrus admin host (CYRUS_ADMIN_HOST). Only the Cyrus admin exists there: /admin/cyrus/**, the admin
// login, the staff 2FA enrolment page, the APIs (each authenticates itself), Next internals and static files. Every
// other path 404s; "/" and "/admin" go to /admin/cyrus.
// ---------------------------------------------------------------------------
export function cyrusAdminHostRoute(a: { pathname: string; search: string; method: string }): HostRoute {
  const p = a.pathname;
  if (p.startsWith("/_next/") || p === "/favicon.ico" || p.startsWith("/.well-known/") || p.startsWith("/vendor/") || STATIC_RE.test(p)) return { kind: "pass" };
  if (p.startsWith("/api/")) return { kind: "pass" };
  if (under(p, "/admin/cyrus") || p === "/admin/login") return { kind: "pass" };
  // Staff without 2FA are sent here by the admin layout (enforce_staff_2fa); account security only.
  if (p === "/dashboard/settings") return { kind: "pass" };
  const read = a.method === "GET" || a.method === "HEAD";
  if (read && (p === "/" || p === "/admin")) return { kind: "redirect", url: "/admin/cyrus", status: 302 };
  if (read && p === "/login") return { kind: "redirect", url: "/admin/login" + a.search, status: 302 };
  return { kind: "notfound" };
}

/** With CYRUS_ADMIN_HOST_ONLY=1: the Cyrus admin paths that must 404 on every other host. */
export const isCyrusAdminPath = (p: string) => under(p, "/admin/cyrus") || under(p, "/api/admin/cyrus");

