import { notFound } from "next/navigation";
import type { User } from "@prisma/client";
import { onCyrusHost } from "@/lib/auth";
import { bridgeConfig } from "@/lib/cyrus/bridge/config";
import { studioViewer } from "@/lib/cyrus/studios/deps";
import { customerAppEnabled, appHref, APP_BASE } from "@/lib/cyrus/app/flags";

export type AppViewer = { user: User; onCyrus: boolean; nxeon: string; href: (internalPath: string) => string };

export async function appViewerOrNull(): Promise<AppViewer | null> {
  if (!customerAppEnabled()) return null;
  const v = await studioViewer().catch(() => null);
  if (!v) return null;
  const onCyrus = await onCyrusHost();
  return { user: v.user, onCyrus, nxeon: bridgeConfig().nxeonOrigin, href: (p) => appHref(p, onCyrus) };
}

export async function appViewer(): Promise<AppViewer> {
  const v = await appViewerOrNull();
  if (!v) notFound();
  return v;
}

export const P = {
  home: APP_BASE, new: `${APP_BASE}/new`, projects: `${APP_BASE}/projects`, assets: `${APP_BASE}/assets`, account: `${APP_BASE}/account`,
  project: (rootId: string) => `${APP_BASE}/projects/${encodeURIComponent(rootId)}`,
};
/** The existing studio pages (same on both hosts: /dashboard/cyrus passes through on cyrus.my). */
export const studioHref = (buildId?: string | null, studio?: string) =>
  !buildId ? "/dashboard/cyrus" : studio ? `/dashboard/cyrus/${encodeURIComponent(buildId)}/studio/${studio}` : `/dashboard/cyrus/${encodeURIComponent(buildId)}`;
import "./app.css";
import { CyrusWordmark } from "@/components/cyrus/brand/CyrusBrand";
import { CyrusTokenChip, CyrusTokensHost } from "@/components/cyrus-tokens";
import { AppNav } from "@/components/cyrus/app/AppNav";
import { appViewer, P } from "./_gate";

export const dynamic = "force-dynamic";

/**
 * Cyrus customer app shell (r39): the landing's language for every customer page (rail + glass + energy accents),
 * inside the Cyrus layout (fonts, .cyrus-root). On cyrus.my the host bar sits above it; in the Nxeon portal the
 * portal frame does. 404 unless the app switch and the studio gate both allow the viewer (see ./_gate.ts).
 */
export default async function CyrusAppLayout({ children }: { children: React.ReactNode }) {
  const v = await appViewer();
  const hrefs = { home: v.href(P.home), new: v.href(P.new), projects: v.href(P.projects), assets: v.href(P.assets), studio: v.onCyrus ? "/studio" : "/dashboard/cyrus", account: v.href(P.account) };
  return (
    <div className="cx-app">
      <div className="cx-aura" aria-hidden="true" />
      <div className="cx-shell">
        <aside className="cx-rail">
          <a className="cx-brand" href={hrefs.home} aria-label="Cyrus App home"><CyrusWordmark height={18} /><small>App</small></a>
          <AppNav hrefs={hrefs} />
          <div className="cx-rail-foot">
            <CyrusTokenChip compact beta={false} />
            <span className="cx-who" title={v.user.email ?? ""}>{v.user.name || v.user.email}</span>
          </div>
        </aside>
        {/* not a second <main>: the portal / Cyrus host shell already provides the page's main landmark (r49 a11y) */}
        <div className="cx-main" id="cx-main">
          {/* Simple (this app: one prompt, then install) / Studio (every studio, chat, attachments). Same account and projects. */}
          <div className="cx-modebar"><div className="cx-seg" role="group" aria-label="View"><a href={hrefs.home} aria-current="page">Simple</a><a href={hrefs.studio}>Studio</a></div></div>
          <div className="cx-page">{children}</div>
        </div>
      </div>
      <CyrusTokensHost />
    </div>
  );
}
import type { Metadata } from "next";
import { db } from "@/lib/db";
import { modBuilderServers } from "@/lib/modbuilder/install";
import { buildTokenState } from "@/lib/cyrus/tokens/state";
import { PLAN_LABEL } from "@/lib/cyrus/engine-core/asset-gate";
import { PERSONAL_SCOPES, SCOPE_LABEL, MAX_ACTIVE_KEYS, toView } from "@/lib/cyrus/app/apikeys";
import { prismaDataStore, prismaKeyStore } from "@/lib/cyrus/app/store";
import { loadPrefs } from "@/lib/cyrus/notify";
import { NOTIFY_EVENTS, notifyEnabled, wants } from "@/lib/cyrus/notify/events";
import { DELETE_CONFIRM } from "@/lib/cyrus/app/data-requests";
import { DELETE_GRACE_DAYS, downloadable, statusLine } from "@/lib/cyrus/app/data-jobs";
import { GRANT_SCOPES } from "@/lib/cyrus/app/grants";
import { Card, Empty } from "@/components/cyrus/app/ui";
import { TokensButton } from "@/components/cyrus/app/TokensButton";
import { ApiKeysPanel, DataPanel, PrefsForm, RevokeGrant } from "@/components/cyrus/app/AccountPanels";
import { IconBell, IconCard, IconExternal, IconKey, IconServer, IconShield, IconUser } from "@/components/cyrus/app/icons";
import { requireModBuilderUser } from "@/lib/modbuilder/access";
import { appGrants } from "../_grants";
import { EMPTY } from "@/lib/cyrus/content/copy";
import { appViewer, P } from "../_gate";
import { StorageView } from "@/components/cyrus/app/StorageView";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Cyrus · Account", robots: { index: false } };

const TABS = [
  { id: "profile", label: "Profile" }, { id: "connections", label: "Nxeon and servers" }, { id: "keys", label: "API keys" },
  { id: "notifications", label: "Notifications" }, { id: "billing", label: "Plan and billing" }, { id: "storage", label: "Storage" }, { id: "data", label: "Your data" },
] as const;
type Tab = (typeof TABS)[number]["id"];
const n = (x: number) => x.toLocaleString("en-US");
const money = (cents: number) => `$${(cents / 100).toFixed(cents % 100 ? 2 : 0)}`;

/** Account (r39): profile, Nxeon connection + servers + grants, personal API keys, notifications, billing, data. */
export default async function CyrusAccount({ searchParams }: { searchParams: Promise<{ tab?: string | string[] }> }) {
  await requireModBuilderUser(); // the preview gate first (same 404 as every Cyrus page), then the app switch
  const v = await appViewer();
  const raw = (await searchParams).tab;
  const tab: Tab = (TABS.find((t) => t.id === raw)?.id ?? "profile") as Tab;
  const uid = v.user.id, now = new Date();
  const tabHref = (t: Tab) => `${v.href(P.account)}?tab=${t}`;

  let body: React.ReactNode = null;
  if (tab === "profile") {
    body = (
      <Card title="Profile" icon={<IconUser />}>
        <div className="cx-list">
          <div className="cx-row"><span className="cx-grow cx-muted">Name</span><b>{v.user.name || "Not set"}</b></div>
          <div className="cx-row"><span className="cx-grow cx-muted">Email</span><span>{v.user.email}</span></div>
          <div className="cx-row"><span className="cx-grow cx-muted">Account</span><span>One Nxeon account for Cyrus and Nxeon: same sign-in, same wallet</span></div>
          <div className="cx-row"><span className="cx-grow cx-muted">Name, email, password, two-factor</span><a className="cx-btn cx-btn-sm" href={`${v.nxeon}/dashboard/settings`}>Edit at Nxeon <IconExternal width={12} height={12} /></a></div>
          <div className="cx-row"><span className="cx-grow cx-muted">Tour</span><a className="cx-btn cx-btn-sm" href={`${v.href(P.home)}?tour=1`}>Take the tour again</a></div>
        </div>
      </Card>
    );
  } else if (tab === "connections") {
    const [servers, grants] = await Promise.all([modBuilderServers(uid).catch(() => []), appGrants(v.nxeon).state(uid).catch(() => ({ available: false as const, reason: "Server connections are unavailable right now." }))]);
    const byServer = grants.available ? new Map(grants.grants.map((g) => [g.serverId, g])) : new Map();
    body = (
      <div style={{ display: "grid", gap: 14 }}>
        <Card title="Nxeon account" icon={<IconShield />}>
          <div className="cx-list">
            <div className="cx-row"><span className="cx-grow cx-muted">Signed in as</span><span>{v.user.email}</span></div>
            <div className="cx-row"><span className="cx-grow cx-muted">Identity</span><span>Sign in with Nxeon (your Nxeon account id, never matched by email)</span></div>
            <div className="cx-row"><span className="cx-grow cx-muted">Wallet and invoices</span><a className="cx-btn cx-btn-sm" href={`${v.nxeon}/dashboard/billing`}>Open at Nxeon <IconExternal width={12} height={12} /></a></div>
          </div>
        </Card>
        <Card title="Servers and what Cyrus may do" icon={<IconServer />}>
          {!grants.available ? <p className="cx-note" style={{ marginTop: 0 }}>{grants.reason}</p> : null}
          {servers.length ? (
            <div className="cx-list">
              {servers.map((s) => {
                const g = byServer.get(s.id);
                return (
                  <div key={s.id} className="cx-row" style={{ alignItems: "flex-start", flexWrap: "wrap" }}>
                    <span className="cx-tile">MC</span>
                    <span className="cx-grow" style={{ minWidth: 220 }}>
                      <span className="cx-t" style={{ display: "block" }}>{s.name}</span>
                      <span className="cx-d" style={{ display: "block", whiteSpace: "normal" }}>{g ? `Connected: ${g.scopes.join(", ")}` : grants.available ? "Not connected" : "Connection not available yet"}</span>
                    </span>
                    {grants.available ? (g ? <RevokeGrant serverId={s.id} /> : <a className="cx-btn cx-btn-sm" href={grants.connectUrl(s.id)}>Connect at Nxeon</a>) : <button type="button" className="cx-btn cx-btn-sm" disabled aria-disabled="true">Connect</button>}
                  </div>
                );
              })}
            </div>
          ) : <Empty>{EMPTY.servers}</Empty>}
          <details style={{ marginTop: 14 }}>
            <summary className="cx-eyebrow" style={{ cursor: "pointer" }}>What a connection allows</summary>
            <p className="cx-muted" style={{ fontSize: 13 }}>You pick the server and tick each permission on a consent screen at Nxeon. You can disconnect at any time; every action is tied to you, the server and the grant, and Nxeon logs it.</p>
            <div className="cx-list">{GRANT_SCOPES.map((s) => <div key={s.id} className="cx-row" style={{ alignItems: "flex-start" }}><span className="cx-mono cx-faint" style={{ minWidth: 130 }}>{s.id}</span><span className="cx-grow"><b style={{ fontWeight: 600 }}>{s.label}</b><div className="cx-faint" style={{ fontSize: 12.5, whiteSpace: "normal" }}>{s.detail}</div></span></div>)}</div>
          </details>
        </Card>
      </div>
    );
  } else if (tab === "keys") {
    const keys = (await prismaKeyStore.listForUser(uid).catch(() => [])).map((k) => toView(k, now));
    body = (
      <Card title="Personal API keys" icon={<IconKey />} aside={`up to ${MAX_ACTIVE_KEYS} active`}>
        <p className="cx-muted" style={{ marginTop: 0, fontSize: 13 }}>Keys act as you, with only the permissions you tick. Starting builds spends your tokens. Keys for the public Cyrus API are not accepted by the API yet: this page manages them ahead of that launch.</p>
        <ApiKeysPanel initial={keys} scopes={PERSONAL_SCOPES.map((id) => ({ id, label: SCOPE_LABEL[id] }))} />
      </Card>
    );
  } else if (tab === "notifications") {
    const prefs = await loadPrefs(uid).catch(() => null);
    body = (
      <Card title="Notifications" icon={<IconBell />}>
        <p className="cx-muted" style={{ marginTop: 0, fontSize: 13 }}>One place for every Cyrus notice. Email comes from Cyrus through Nxeon&apos;s mail. {notifyEnabled() ? "Your choices apply to every new notice." : "Notices are not being sent yet; your choices apply once they are."}</p>
        {prefs ? <PrefsForm events={NOTIFY_EVENTS.map((e) => ({ id: e.id, label: e.label, hint: e.what, locked: !!e.required?.length }))} prefs={Object.fromEntries(NOTIFY_EVENTS.map((e) => [e.id, { email: wants(prefs, e.id, "email"), inApp: wants(prefs, e.id, "inApp") }]))} /> : <p className="cx-error">Preferences could not be loaded.</p>}
      </Card>
    );
  } else if (tab === "billing") {
    const t = await buildTokenState(v.user).catch(() => null);
    body = (
      <div style={{ display: "grid", gap: 14 }}>
        <Card title="Plan and tokens" icon={<IconCard />}>
          {t?.active ? (
            <div className="cx-list">
              <div className="cx-row"><span className="cx-grow cx-muted">Plan</span><b>{t.plan?.active ? PLAN_LABEL[t.plan.tier] ?? t.plan.tier : "No plan"}</b></div>
