/** Public paths on the Cyrus host (cyrus.my) -> the app's internal tree. Used by the dual-host routing. */
export const APP_BASE = "/dashboard/cyrus/app";
export const CYRUS_APP_PATHS: Record<string, string> = {
  "/home": APP_BASE,
  "/new": `${APP_BASE}/new`,
  "/account": `${APP_BASE}/account`,
  "/projects": `${APP_BASE}/projects`,
  "/assets": `${APP_BASE}/assets`,
};

/** cyrus.my public path for an internal app path (identity elsewhere): used for links that must work on both hosts. */
export function appHref(path: string, onCyrusHost: boolean): string {
  if (!onCyrusHost || !path.startsWith(APP_BASE)) return path;
  const rest = path.slice(APP_BASE.length);
  if (rest === "" || rest.startsWith("?")) return "/home" + rest;
  return rest;
}

