export function Modal({ title, sub, onClose, children, wide }: { title: string; sub?: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { window.removeEventListener("keydown", k); document.body.style.overflow = prev; };
  }, [onClose]);
  // Portalled to <body> so it sits above the portal's own top bar; .cy-tokens carries the theme.
  const [host, setHost] = useState<HTMLElement | null>(null);
  useEffect(() => setHost(document.body), []);
  if (!host) return null;
  return createPortal(
    <div className="cy-tokens cy-modal-back" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <NeonDefs />
      <div className={`cy-modal ${wide ? "wide" : ""}`}>
        <div className="cy-modal-h">
          <div className="flex min-w-0 flex-col gap-1">
            <h2>{title}</h2>
            {sub && <p>{sub}</p>}
          </div>
          <button type="button" className="cy-ib ml-auto" onClick={onClose} aria-label="Close"><CyIcon name="x" size={14} /></button>
        </div>
        {children}
      </div>
    </div>,
    host,
  );
}

