function CommunityInstallModal({ slug, buildId, title, label, onClose }: { slug: string; buildId: string; title: string; label: string; onClose: () => void }) {
  const [servers, setServers] = useState<MbServer[] | null>(null);
  const [sel, setSel] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);
  useEffect(() => {
    void myCyrusServers().then((r) => {
      const list = "servers" in r ? r.servers : [];
      setServers(list);
      setSel(list.find((s) => s.compatible)?.id ?? null);
    }).catch(() => setServers([]));
  }, []);
  const go = async () => {
