import type { User } from "@prisma/client";
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import { loadTokenConfig, PLAN_TIERS, type PlanTier } from "./config";
import { effectiveTier, modelsFor, TIER_LABEL, TIER_MODELS } from "./economy";
import { ledgerPage, tokenSummary } from "./ledger";
import { tokensActiveFor } from "./access";
import { ensureStarterTokens } from "./starter";
import { maybeReconcileUser, planPrices } from "./billing";
import { rolloverRulesCopy, serverGrantRulesCopy } from "./rollover";
import { historyLabel, type TokenHistory, type TokenState } from "./view";
import { walletPayEnabled } from "./purchase";

// Stripe is the host's (host.billing.stripe); same rule as lib/stripe stripeConfigured inside Nxeon.
const stripeConfigured = () => !!getHost().billing.stripe?.configured();

/** r44: the wallet option in the tokens screen (only with CYRUS_WALLET_PAY and a host wallet). */
async function walletOffer(userId: string): Promise<TokenState["wallet"]> {
  const w = getHost().billing.wallet;
  if (!walletPayEnabled() || !w) return null;
  const nxeon = (process.env.APP_URL || "https://nxeon.cloud").replace(/\/+$/, "");
  return { balanceCents: await w.balance(userId).catch(() => null), addFundsUrl: `${nxeon}/dashboard/billing` };
}

export async function buildTokenState(user: User, opts: { reconcile?: boolean } = {}): Promise<TokenState> {
  const cfg = await loadTokenConfig();
  const active = await tokensActiveFor(user, cfg);
  if (active) await ensureStarterTokens(user, cfg);
  if (active && opts.reconcile !== false) await maybeReconcileUser(user.id);
  const now = new Date();
  const [sum, plan, acct, prices] = await Promise.all([
    tokenSummary(user.id, now),
    db.cyrusPlan.findUnique({ where: { userId: user.id } }),
    db.cyrusTokenAccount.findUnique({ where: { userId: user.id }, select: { tierOverride: true, tierOverrideUntil: true } }),
    active && stripeConfigured() ? planPrices(cfg) : Promise.resolve({ katara: null, saka: null, all: null } as Awaited<ReturnType<typeof planPrices>>),
  ]);
  const tier = effectiveTier({ plan, override: acct?.tierOverride, overrideUntil: acct?.tierOverrideUntil, now, cfg });
  const planActive = !!plan && effectiveTier({ plan, now, cfg }) !== "free";
  return {
    active,
    enforce: cfg.enforce,
    balance: sum.balance,
    reserved: sum.reserved,
    available: sum.available,
    lowBalance: cfg.lowBalance,
    nextExpiry: sum.nextExpiry,
    tier,
    models: modelsFor(tier),
    plan: plan ? {
      tier: plan.tier as PlanTier, priceTier: plan.priceTier as PlanTier, status: plan.status,
      currentPeriodEnd: plan.currentPeriodEnd?.toISOString() ?? null, cancelAtPeriodEnd: plan.cancelAtPeriodEnd, active: planActive,
    } : null,
    plans: PLAN_TIERS.map((t) => ({
      tier: t, name: TIER_LABEL[t], priceCents: prices[t]?.unitAmount ?? cfg.plan.cents[t], tokens: cfg.plan.tokens[t], models: TIER_MODELS[t], purchasable: !!prices[t],
    })),
    topup: { enabled: cfg.topup.enabled, minCents: cfg.topup.minCents, maxCents: cfg.topup.maxCents, tokensPerUsd: cfg.topup.tokensPerUsd },
    wallet: await walletOffer(user.id),
    reserve: cfg.reserve,
    rolloverMonths: cfg.plan.rolloverMonths,
    frozen: sum.frozen,
    rules: { plan: rolloverRulesCopy(cfg), servers: serverGrantRulesCopy(cfg) },
    payments: stripeConfigured(),
  };
}

export async function buildHistory(userId: string, before?: string | null): Promise<TokenHistory> {
  const { rows, more } = await ledgerPage(userId, { take: 30, before });
  return {
    more,
    rows: rows
      // A hold and its settle are one event for the customer: show the settle (it carries the hold).
      .filter((r) => r.kind !== "reserve" || !rows.some((x) => x.buildId === r.buildId && (x.kind === "spend" || x.kind === "release")))
      .map((r) => ({
        id: r.id, kind: r.kind, delta: r.delta, at: r.createdAt.toISOString(), source: r.source, model: r.model, buildId: r.buildId,
        hold: (r.meta as { hold?: number } | null)?.hold ?? null,
        label: historyLabel(r),
      })),
  };
}
