// Install a finished Cyrus / Mod Builder build onto one of the user's Minecraft servers.
//
// Since 2026-10-07 (Cyrus mods) this goes THROUGH THE MODS ENGINE instead of a
// direct copy: the build's chain gets a GameMod row (source "cyrus",
// lib/cyrus-mods/registry.ts), the ServerMod row is queued INSTALLING/UPDATING
// with targetVersionId = this build, and the worker's GAME_MOD_SYNC places the
// jar with lib/mods/engine.ts (state file, backup, staged write, rollback). So
// the Mods tab lists it, can switch it off/on, update it, roll it back and
// uninstall it like any other plugin.
//
// A jar a PRE-ENGINE builder install left in plugins/ (not in the engine's state
// file) is backed up to /root/.nxeon-mods/backups/<stamp>-cyrus-adopt-<name>/
// and removed first, so the server never loads two copies of one plugin.
// The route then waits briefly for the job so the Cyrus UI can say "done".
import { flightBlocks } from "../cyrus/testflight/gate";
import type { ModBuild } from "@prisma/client";
import { enqueueModOp } from "../mods/queue";
import { loadState, ownerOf } from "../mods/engine";
import { ensureCyrusGameMod, loadChain, rootOf } from "../cyrus-mods/registry";
import { syncCyrusModPage } from "../cyrus-mods/pages";
import { db } from "../db";
import { SANDBOX } from "../sandbox";
import { familyFor } from "../game-config";
import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest, type GuestFs } from "../mods/guest-fs";
import { SshGuestFs } from "../../worker/mods-guest-ssh";
import { cyrusConfig } from "../cyrus/config";

const MC_BASE = cyrusConfig().guest.mcBase;
const PLUGINS = `${MC_BASE}/plugins`;
const BACKUPS = cyrusConfig().guest.modsBackupDir;
/** Generated plugins target the Paper API (Adventure etc.), so Spigot/Bukkit can't load them, and they aren't Folia-safe. */
export const MB_INSTALL_VARIANTS = ["paper", "purpur"];

import type { MbServer } from "../cyrus/builder/types";
export type { MbServer };

/** The user's Minecraft servers, each marked whether a builder plugin can go on it. */
export async function modBuilderServers(userId: string): Promise<MbServer[]> {
  const rows = await db.server.findMany({
    where: { userId, status: { notIn: ["DELETING"] } },
    include: { osTemplate: true, gamePlan: true },
    orderBy: { createdAt: "asc" },
  });
  const out: MbServer[] = [];
  for (const s of rows) {
    if (familyFor(s) !== "minecraft") continue;
    const variant = (s.gameVariant || "vanilla").toLowerCase();
    const okVariant = MB_INSTALL_VARIANTS.includes(variant);
    // The engine installs onto the running server (same rule as the Mods tab).
    const okStatus = s.status === "RUNNING";
    out.push({
      id: s.id,
      name: s.label || s.hostname,
      variant,
      status: s.status,
      compatible: okVariant && okStatus,
      reason: !okVariant ? `Runs ${variant[0].toUpperCase() + variant.slice(1)}; plugins need Paper or Purpur` : !okStatus ? (s.status === "STOPPED" ? "Server is stopped — start it to install" : `Server is ${s.status.toLowerCase()}`) : undefined,
    });
  }
  return out;
}

function stamp(d = new Date()) {
  return d.toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
}

export type InstallResult =
  | { ok: true; path: string; replaced: string[]; backupDir: string | null; serverName: string; queued: boolean; jobId: string; modId: string }
  | { ok: false; error: string };

"use server";

/**
 * Cyrus mod lifecycle on the customer's own servers (docs/DOCUMENTATION.md "Cyrus mod lifecycle"):
 * install plans with version checks and the confirm step, install from Cyrus or NxLabs, switch
 * on/off, update one / update all, per-mod auto-update opt-in, and the creator's warnings.
 *
 * Every server change is the normal engine path (ServerMod -> one GAME_MOD_SYNC job under the
 * per-server lock, lib/mods/queue.ts): backup first, staged write, rollback on failure.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { cyrusDb } from "./cyrus/db";
import { requireUser } from "./auth";
import { SANDBOX } from "./sandbox";
import { familyFor } from "./game-config";
import { withServerJobLock } from "./job-guard";
import { enqueueModOp } from "./mods/queue";
import { toggleDecision } from "./mods/toggle-policy";
import { engineInstallerFor } from "./mods/installers";
import { CYRUS_SOURCE } from "./mods/installers/cyrus";
import { installBuildToServer } from "./modbuilder/install";
import { cyrusAccessFor } from "./cyrus-mods/gate";
import { gamePower } from "./actions-game-control";
import { confirmPlan } from "./cyrus/lifecycle/install-plan";
import { installPlansWithConfig } from "./modbuilder/config-delivery";
import { installPlansFor, lifecycleForServer, publicInstallAllowed, toAlertViews, type CreatorAlertView, type CyrusLifecycleRow, type ServerPlan } from "./cyrus/lifecycle/server";

const ID = /^[A-Za-z0-9_-]{1,64}$/;
const live = () => SANDBOX || process.env.ENABLE_REAL_GAMEMODS === "1";

async function installableBuild(buildId: string) {
  const user = await requireUser();
  if (typeof buildId !== "string" || !ID.test(buildId)) return { user, build: null };
  const build = await cyrusDb.modBuild.findUnique({ where: { id: buildId } });
  if (!build || build.status !== "succeeded" || !build.jarName) return { user, build: null };
  if (build.userId !== user.id) {
    if (!(await cyrusAccessFor(user)).allowed || !(await publicInstallAllowed(build, user.id))) return { user, build: null };
  }
  return { user, build };
}

/** The install plan for every Minecraft server the viewer owns (dialog step 1). */
export async function getCyrusInstallPlans(buildId: string): Promise<{ error?: string; game?: string; plans?: ServerPlan[]; installsLive?: boolean; own?: boolean }> {
  try {
    const { user, build } = await installableBuild(buildId);
    if (!build) return { error: "This version can't be installed." };
    const r = await installPlansWithConfig(build, user.id);
    return { game: r.game, plans: r.plans, installsLive: live(), own: build.userId === user.id };
  } catch {
    return { error: "Couldn't check your servers." };
  }
}

export type CyrusInstallResult = { ok?: true; error?: string; queued?: boolean; restarted?: boolean; restartNote?: string | null; replaced?: string[]; serverName?: string; modId?: string };

/** Install (or update to) this build on one server after the customer confirmed the plan's warnings. */
export async function installCyrusMod(buildId: string, serverId: string, acked: string[], opts: { restart?: boolean } = {}): Promise<CyrusInstallResult> {
  const { user, build } = await installableBuild(buildId);
  if (!build) return { error: "This version can't be installed." };
  if (typeof serverId !== "string" || !ID.test(serverId)) return { error: "Pick a server." };
  const ack = Array.isArray(acked) ? acked.filter((a) => typeof a === "string").slice(0, 20) : [];
  const { plans } = await installPlansFor(build, user.id);
  const sp = plans.find((p) => p.server.id === serverId);
  if (!sp) return { error: "That server isn't one of your Minecraft servers." };
  if (sp.plan.op === "none") return { error: "That version is already on the server." };
  const ok = confirmPlan(sp.plan, ack);
  if (!ok.ok) return { error: ok.error };
  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was installed." };

  const r = await installBuildToServer(build, user.id, serverId, { allowPublic: build.userId !== user.id });
  if (!r.ok) return { error: r.error };
  let restarted = false;
  let restartNote: string | null = null;
  if (opts.restart && sp.plan.restart === "required") {
    if (r.queued) restartNote = "The install is still queued. Restart from the Mods tab once it shows as installed.";
    else {
      const p = await gamePower(serverId, "restart");
      restarted = p.ok;
      if (!p.ok) restartNote = p.error;
    }
  }
  if (build.userId === user.id) {
    await cyrusDb.modBuild.update({ where: { id: build.id }, data: { lastInstall: { serverId, serverName: r.serverName, at: new Date().toISOString(), replaced: r.replaced, backupDir: r.backupDir, restarted } } }).catch(() => {});
  }
  await db.auditLog.create({ data: { userId: user.id, action: "cyrus.install", detail: `${build.id} -> ${serverId} acked=${ack.join(",")}${build.userId !== user.id ? " (published, other creator)" : ""}`.slice(0, 900) } }).catch(() => {});
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, queued: r.queued, restarted, restartNote, replaced: r.replaced, serverName: r.serverName, modId: r.modId };
}

async function ownedCyrusRows(serverId: string) {
  const user = await requireUser();
  if (typeof serverId !== "string" || !ID.test(serverId)) throw new Error("Not found");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true } });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) throw new Error("Not found");
  return { user, server };
}

/** Lifecycle rows for one server (Mods tab, NxLabs "On my servers"). */
export async function getCyrusLifecycle(serverId: string): Promise<{ error?: string; rows?: CyrusLifecycleRow[] }> {
  try {
    await ownedCyrusRows(serverId);
    return { rows: await lifecycleForServer(serverId) };
  } catch {
    return { error: "Couldn't load your Cyrus mods." };
  }
}

/** Switch a Cyrus mod off (kept on disk, config kept) or back on. */
export async function setCyrusModEnabled(serverId: string, modId: string, on: boolean): Promise<{ ok?: true; error?: string }> {
  let ctx;
  try {
    ctx = await ownedCyrusRows(serverId);
  } catch {
    return { error: "Not found." };
  }
  const { user, server } = ctx;
  if (typeof modId !== "string" || !ID.test(modId)) return { error: "Not found." };
  const row = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } }, include: { mod: true } });
  if (!row || row.mod.source !== CYRUS_SOURCE) return { error: "Not found." };
  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was changed." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first: mods are changed on the running server." };
  const family = familyFor(server) ?? row.mod.gameFamily;
  const d = toggleDecision({ family, variant: server.gameVariant ?? null, mod: row.mod, engine: !!engineInstallerFor(family, row.mod.source) });
  if (!d.allowed) return { error: d.reason };
  if (on && row.status !== "DISABLED") return { error: `${row.mod.name} is already on.` };
  if (!on && row.status !== "INSTALLED") return { error: `${row.mod.name} is ${row.status.toLowerCase()} right now.` };
  const r = await enqueueModOp(serverId, modId, on ? "enable" : "disable", { userId: user.id, slug: row.mod.slug });
  if (!r.ok) return { error: r.error };
  if (on) await cyrusDb.cyrusModSignal.updateMany({ where: { serverId, modId, kind: "AUTO_DISABLED", clearedAt: null }, data: { clearedAt: new Date() } }).catch(() => {});
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

/**
/**
 * The lifecycle state of a Cyrus mod on one server (PURE, client-safe).
 *
 * The DB row (ServerMod.status) says what the ENGINE did; this adds what the customer needs to
 * know on top: does it need a restart, did it break, is it out of date. One function derives the
 * state everyone shows (Mods tab row, server card, server banner, NxLabs "On my servers"), and
 * one transition table documents and tests how it moves (docs/DOCUMENTATION.md has the diagram).
 *
 *   resting:   enabled · disabled · pending_restart · failed · broken · outdated
 *   in flight: installing · updating · enabling · disabling · removing
 *
 * Priority when several are true: in flight > failed > broken > disabled > pending_restart >
 * outdated > enabled. ("Broken" outranks "Disabled" only while it is still switched on: a mod we
 * auto-disabled is Disabled, with the reason.)
 */
import type { OutdatedReason } from "./compat";

export type LifecycleState =
  | "installing" | "updating" | "enabling" | "disabling" | "removing"
  | "enabled" | "disabled" | "pending_restart" | "failed" | "broken" | "outdated";

export type LifecycleAction = "enable" | "disable" | "update" | "rollback" | "restart" | "remove" | "retry" | "rebuild";

export type LifecycleInput = {
  /** ServerMod.status */
  status: string;
