export type NavHrefs = { home: string; new: string; projects: string; assets: string; studio: string; account: string };

export function AppNav({ hrefs }: { hrefs: NavHrefs }) {
  const path = usePathname() || "";
  const at = (k: keyof NavHrefs) => {
    const internal = { home: "/dashboard/cyrus/app", new: "/dashboard/cyrus/app/new", projects: "/dashboard/cyrus/app/projects", assets: "/dashboard/cyrus/app/assets", studio: "/dashboard/cyrus", account: "/dashboard/cyrus/app/account" }[k];
