async function chainsFor(roots: string[]): Promise<Map<string, ModBuild[]>> {
  const out = new Map<string, ModBuild[]>();
  if (!roots.length) return out;
  const rows = await db.modBuild.findMany({ where: { OR: [{ id: { in: roots } }, { rootBuildId: { in: roots } }] }, orderBy: { createdAt: "asc" } });
  for (const b of rows) {
    const r = b.rootBuildId ?? b.id;
    out.set(r, [...(out.get(r) ?? []), b]);
  }
  return out;
}

