export async function updateAllCyrusMods(serverId: string): Promise<{ ok?: true; error?: string; count?: number }> {
  let ctx;
  try {
    ctx = await ownedCyrusRows(serverId);
  } catch {
    return { error: "Not found." };
  }
  const { user, server } = ctx;
  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was queued." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first." };
  const rows = (await lifecycleForServer(serverId)).filter((r) => r.updateAvailable && r.latestBuildId && r.view.state !== "disabled" && !["installing", "updating", "enabling", "disabling", "removing", "failed"].includes(r.view.state));
  if (!rows.length) return { error: "Every Cyrus mod here is on its newest version." };
  // Published versions only for other creators' mods (re-checked by the engine's jar source too).
  const targets: { modId: string; buildId: string; slug: string }[] = [];
  for (const r of rows.slice(0, 25)) {
    const b = await cyrusDb.modBuild.findUnique({ where: { id: r.latestBuildId! } });
    if (!b || !(await publicInstallAllowed(b, server.userId))) continue;
    const gm = await db.gameMod.findUnique({ where: { id: r.modId }, select: { slug: true } });
    targets.push({ modId: r.modId, buildId: b.id, slug: gm?.slug ?? r.modId });
  }
  if (!targets.length) return { error: "No update can be applied right now." };
  const q = await withServerJobLock(serverId, async (tx) => {
    const inflight = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
    if (inflight > 0) return { ok: false as const, error: "Another operation is already running on this server. Try again when it finishes." };
    const cur = await tx.serverMod.findMany({ where: { serverId, modId: { in: targets.map((t) => t.modId) } }, select: { modId: true, status: true } });
    if (cur.some((c) => c.status !== "INSTALLED")) return { ok: false as const, error: "A mod changed while you were looking. Refresh and try again." };
    for (const t of targets) await tx.serverMod.update({ where: { serverId_modId: { serverId, modId: t.modId } }, data: { status: "UPDATING", error: null, targetVersionId: t.buildId } });
    const job = await tx.job.create({ data: { type: "GAME_MOD_SYNC", serverId, payload: { ops: targets.map((t) => ({ modId: t.modId, op: "update" })), batch: true, cyrusUpdateAll: true } }, select: { id: true } });
    return { ok: true as const, jobId: job.id };
  });
  if (!q.ok) return { error: q.error };
  await db.auditLog.createMany({ data: targets.map((t) => ({ userId: user.id, action: "gameserver.mod.update", detail: `${serverId} mod=${t.slug} version=${t.buildId} batch=${q.jobId} cyrus-update-all` })) }).catch(() => {});
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, count: targets.length };
}

/** Per-mod opt-in: apply new versions of this Cyrus mod automatically (the lifecycle sweep does it, server empty, off-peak). */
export async function setCyrusAutoUpdate(serverId: string, modId: string, on: boolean): Promise<{ ok?: true; error?: string }> {
  try {
    await ownedCyrusRows(serverId);
  } catch {
    return { error: "Not found." };
  }
  if (typeof modId !== "string" || !ID.test(modId)) return { error: "Not found." };
  const row = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } }, include: { mod: { select: { source: true } } } });
  if (!row || row.mod.source !== CYRUS_SOURCE) return { error: "Not found." };
  await db.serverMod.update({ where: { id: row.id }, data: { autoUpdate: on ? "AUTO" : "OFF" } });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

