// Help center URLs (r50). PURE, Edge-safe (middleware imports it). On the Cyrus host the public path is /help; on
// every other host the same pages live at /cyrus-help (an internal-looking name that cannot clash with Nxeon's /help).
export const HELP_BASE_INTERNAL = "/cyrus-help";
export const HELP_BASE_PUBLIC = "/help";

/** Public help path on the Cyrus host -> internal path (null = not a help path). `/plans` is the pricing page. */
export function helpPath(p: string): string | null {
  if (p === HELP_BASE_PUBLIC) return HELP_BASE_INTERNAL;
  if (p === "/plans") return `${HELP_BASE_INTERNAL}/plans`;
  const m = /^\/help\/([a-z0-9][a-z0-9-]{0,63})$/.exec(p);
  return m ? `${HELP_BASE_INTERNAL}/${m[1]}` : null;
}
