"use client";
// Per-server Cyrus mod controls for the native /servers page: switch on/off, auto-update, update all. Every action is
// the existing lifecycle server action (lib/actions-cyrus-lifecycle.ts), which re-checks the owner and the engine rules.
import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import { setCyrusAutoUpdate, setCyrusModEnabled, updateAllCyrusMods } from "@/lib/actions-cyrus-lifecycle";

export type ModRowView = {
  modId: string; name: string; state: string; label: string; tone: "ok" | "info" | "warn" | "bad" | "muted";
  note: string | null; installed: string | null; latest: string | null; updateAvailable: boolean; autoUpdate: boolean;
  /** href of the project in this app when the viewer owns it (opens the install dialog there), else null. */
  projectHref: string | null;
};

const PILL: Record<ModRowView["tone"], string> = { ok: "cx-ok", info: "cx-wait", warn: "cx-warn", bad: "cx-bad", muted: "cx-none" };
const FLIGHT = new Set(["installing", "updating", "enabling", "disabling", "removing"]);

export function ServerMods({ serverId, rows, canChange }: { serverId: string; rows: ModRowView[]; canChange: boolean }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const run = (key: string, fn: () => Promise<{ ok?: true; error?: string; count?: number }>, done: (r: { count?: number }) => string) => {
    setBusy(key); setMsg(null);
    start(async () => {
      const r = await fn().catch(() => ({ error: "Couldn't reach the server. Try again." } as { ok?: true; error?: string; count?: number }));
      setBusy(null);
      setMsg(r.error ? { ok: false, text: r.error } : { ok: true, text: done(r) });
      if (!r.error) router.refresh();
    });
  };
  const updatable = rows.filter((r) => r.updateAvailable && r.state !== "disabled" && !FLIGHT.has(r.state) && r.state !== "failed").length;
  return (
    <div>
      <div className="cx-list">
        {rows.map((r) => {
          const inFlight = FLIGHT.has(r.state);
          const on = r.state !== "disabled";
          return (
            <div key={r.modId} className="cx-row" style={{ flexWrap: "wrap", alignItems: "flex-start" }}>
              <span className="cx-grow" style={{ minWidth: 200 }}>
                <span className="cx-t" style={{ display: "block" }}>{r.name}</span>
                <span className="cx-d" style={{ display: "block", whiteSpace: "normal" }}>
                  {r.installed ? `Installed ${r.installed}` : "Installed"}{r.updateAvailable && r.latest ? ` · ${r.latest} is available` : ""}
                  {r.note ? ` · ${r.note}` : ""}
                </span>
              </span>
              <span className={`cx-pill ${PILL[r.tone]}`}>{r.label}</span>
              {canChange ? (
                <span style={{ display: "inline-flex", gap: 6, flexWrap: "wrap" }}>
                  <button type="button" className="cx-btn cx-btn-sm" disabled={pending || inFlight || r.state === "failed"} aria-label={`${on ? "Disable" : "Enable"} ${r.name}`}
                    onClick={() => run(`t:${r.modId}`, () => setCyrusModEnabled(serverId, r.modId, !on), () => (on ? `${r.name} is being switched off.` : `${r.name} is being switched on.`))}>
                    {busy === `t:${r.modId}` ? "Working…" : on ? "Disable" : "Enable"}
                  </button>
                  <button type="button" className="cx-btn cx-btn-sm" aria-pressed={r.autoUpdate} disabled={pending}
                    title="Apply new versions of this mod automatically, when the server is empty"
                    onClick={() => run(`a:${r.modId}`, () => setCyrusAutoUpdate(serverId, r.modId, !r.autoUpdate), () => (r.autoUpdate ? "Auto-update is off." : "Auto-update is on."))}>
                    Auto-update: {r.autoUpdate ? "on" : "off"}
                  </button>
                  {r.projectHref ? <a className="cx-btn cx-btn-sm" href={r.projectHref}>{r.updateAvailable ? "Update in project" : "Open project"}</a> : null}
                </span>
              ) : null}
            </div>
          );
        })}
      </div>
      {canChange && updatable > 0 ? (
        <p style={{ margin: "10px 0 0" }}>
          <button type="button" className="cx-btn cx-btn-pri cx-btn-sm" disabled={pending}
            onClick={() => run(`u:${serverId}`, () => updateAllCyrusMods(serverId), (r) => `${r.count ?? updatable} update${(r.count ?? updatable) === 1 ? "" : "s"} queued. The server keeps a backup of what it replaces.`)}>
            {busy === `u:${serverId}` ? "Queuing…" : `Update all (${updatable})`}
          </button>
        </p>
      ) : null}
      {!canChange ? <p className="cx-note" style={{ marginBottom: 0 }}>Start this server to change its mods; changes are made on the running server.</p> : null}
      {msg ? <p role="status" className={msg.ok ? "cx-note" : "cx-error"} style={{ marginBottom: 0 }}>{msg.text}</p> : null}
    </div>
  );
}
