import type { Metadata } from "next";
import { cyrusDb } from "@/lib/cyrus/db";
import { getHost } from "@/lib/cyrus/host";
import { modBuilderServers } from "@/lib/modbuilder/install";
import { lifecycleForServer, serverGameVersion } from "@/lib/cyrus/lifecycle/server";
import { Card, Empty } from "@/components/cyrus/app/ui";
import { IconExternal, IconServer } from "@/components/cyrus/app/icons";
import { ServerMods, type ModRowView } from "@/components/cyrus/app/ServerMods";
import { requireModBuilderUser } from "@/lib/modbuilder/access";
import { EMPTY } from "@/lib/cyrus/content/copy";
import { appViewer, P } from "../_gate";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Cyrus · Servers", robots: { index: false } };

const STATUS: Record<string, [string, string]> = { RUNNING: ["cx-ok", "Online"], STOPPED: ["cx-none", "Stopped"], PROVISIONING: ["cx-wait", "Starting up"], STARTING: ["cx-wait", "Starting"] };
const MAX_SERVERS = 25;

/**
 * My servers (cyrus.my /servers): the account's Minecraft servers that can take Cyrus mods, the Cyrus mods on each with
 * their on/off state and the install/update actions of the lifecycle API. Only panel work (console, files, billing)
 * stays on Nxeon, behind one clearly labelled link that opens a new tab.
 */
export default async function CyrusServers() {
  await requireModBuilderUser(); // the preview gate first (same 404 as every Cyrus page), then the app switch
  const v = await appViewer();
  const servers = (await modBuilderServers(v.user.id).catch(() => [])).slice(0, MAX_SERVERS);
  const data = await Promise.all(servers.map(async (s) => {
    const [rows, row] = await Promise.all([lifecycleForServer(s.id).catch(() => []), getHost().servers.get(s.id).catch(() => null)]);
    const version = row ? await serverGameVersion(row).catch(() => null) : null;
    return { s, rows, version };
  }));
  const roots = [...new Set(data.flatMap((d) => d.rows.map((r) => r.rootBuildId)))];
  const mine = new Set(roots.length ? (await cyrusDb.modBuild.findMany({ where: { id: { in: roots }, userId: v.user.id }, select: { id: true } }).catch(() => [])).map((b) => b.id) : []);
  const manage = (id: string) => `${v.nxeon}/dashboard/servers/${encodeURIComponent(id)}`;

  return (
    <>
      <header className="cx-head">
        <div><div className="cx-eyebrow">Cyrus</div><h1 className="cx-h1">My servers</h1><p className="cx-sub">Your Minecraft servers and the Cyrus mods on them. Switch a mod off, update it, or install a new one from its project.</p></div>
        <a className="cx-btn cx-btn-energy" href={v.href(P.projects)}>Install a mod</a>
      </header>
      {data.length === 0 ? (
        <Card title="Servers" icon={<IconServer />}>
          <Empty action={<a className="cx-btn cx-btn-sm" href={`${v.nxeon}/dashboard/deploy`} target="_blank" rel="noopener noreferrer">Get a Minecraft server on Nxeon <IconExternal width={12} height={12} /></a>}>{EMPTY.servers}</Empty>
        </Card>
      ) : (
        <div style={{ display: "grid", gap: 14 }}>
          {data.map(({ s, rows, version }) => {
            const [tone, label] = STATUS[s.status] ?? ["cx-wait", s.status.charAt(0) + s.status.slice(1).toLowerCase()];
            const views: ModRowView[] = rows.map((r) => ({
              modId: r.modId, name: r.name, state: r.view.state, label: r.view.label, tone: r.view.tone, note: r.view.notes[0] ?? null,
              installed: r.installedLabel, latest: r.latestLabel, updateAvailable: r.updateAvailable, autoUpdate: r.autoUpdate,
              projectHref: mine.has(r.rootBuildId) ? v.href(P.project(r.rootBuildId)) : null,
            }));
            return (
              <section key={s.id} id={`s-${s.id}`} className="cx-card cx-reveal" aria-label={s.name}>
                <div className="cx-card-h">
                  <span className="cx-glyph"><IconServer /></span><h2 className="cx-h2">{s.name}</h2>
                  <span className="cx-aside"><span className={`cx-pill ${tone}`}>{label}</span></span>
                </div>
                <p className="cx-muted" style={{ margin: "0 0 10px", fontSize: 13 }}>
                  Minecraft{version ? ` ${version}` : ""} · {s.variant ? s.variant.charAt(0).toUpperCase() + s.variant.slice(1) : "Vanilla"}
                  {s.compatible ? "" : ` · ${s.reason ?? "Can't take Cyrus mods right now"}`}
                </p>
                {views.length ? <ServerMods serverId={s.id} rows={views} canChange={s.status === "RUNNING"} /> : <p className="cx-muted" style={{ margin: 0 }}>No Cyrus mods on this server yet. Open a project and press Install to put one here.</p>}
                <p style={{ margin: "12px 0 0", display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
                  <a className="cx-btn cx-btn-sm" href={manage(s.id)} target="_blank" rel="noopener noreferrer" title="Console, files, backups and billing live in the Nxeon panel; opens in a new tab">Manage on Nxeon <IconExternal width={12} height={12} /></a>
                  <span className="cx-faint" style={{ fontSize: 12 }}>Console, files and billing are on Nxeon.</span>
                </p>
              </section>
            );
          })}
        </div>
      )}
    </>
  );
}
