// Cyrus dual-host routing (CYRUS_DOMAIN_MODE): pure decisions + the middleware wiring, incl. "flag off = unchanged".
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { NextRequest } from "next/server";
import { bridgeConfig, isCyrusHost, CYRUS_HOST_HEADER } from "../lib/cyrus/bridge/config";
import { cyrusHostRoute, safeCyrusNext } from "../lib/cyrus/bridge/routing";

const ON = { CYRUS_DOMAIN_MODE: "1", APP_URL: "https://nxeon.cloud" };
const cfg = bridgeConfig(ON);
const route = (pathname: string, method = "GET", search = "") => cyrusHostRoute({ pathname, search, method, cfg });

describe("bridge config", () => {
  it("is off unless CYRUS_DOMAIN_MODE=1", () => {
    assert.equal(bridgeConfig({}).enabled, false);
    assert.equal(isCyrusHost("cyrus.my", bridgeConfig({})), false);
    assert.equal(isCyrusHost("cyrus.my:443", cfg), true);
    assert.equal(isCyrusHost("CYRUS.MY", cfg), true);
    assert.equal(isCyrusHost("evil-cyrus.my", cfg), false);
    assert.equal(isCyrusHost("nxeon.cloud", cfg), false);
    assert.equal(cfg.cyrusOrigin, "https://cyrus.my");
    assert.equal(cfg.nxeonOrigin, "https://nxeon.cloud");
  });
});

describe("Cyrus host routes", () => {

  });
});

describe("middleware wiring", () => {
  const run = async (url: string, host: string, env: Record<string, string | undefined>, hdrs: Record<string, string> = {}) => {
    const saved = { ...process.env };
    Object.assign(process.env, env);
    try {
      const { middleware } = await import("../middleware");
      return middleware(new NextRequest(url, { headers: { host, ...hdrs } }));
    } finally {
      for (const k of Object.keys(env)) if (saved[k] === undefined) delete process.env[k]; else process.env[k] = saved[k];
    }
  };
  const fwd = (res: Response, name: string) => res.headers.get(`x-middleware-request-${name}`);

  it("flag off: cyrus.my is just another host (no marker, no rewrite) and the spoofed marker is stripped", async () => {
    const res = await run("https://cyrus.my/dashboard/servers", "cyrus.my", { CYRUS_DOMAIN_MODE: undefined }, { [CYRUS_HOST_HEADER]: "1" });
    assert.equal(res.headers.get("x-middleware-rewrite"), null);
    assert.equal(res.status, 200);
    assert.equal(fwd(res, CYRUS_HOST_HEADER), null);
  });
  it("flag on, Nxeon host: unchanged and the spoofed marker is stripped", async () => {
    const res = await run("https://nxeon.cloud/dashboard/cyrus", "nxeon.cloud", ON, { [CYRUS_HOST_HEADER]: "1" });
    assert.equal(res.status, 200);
    assert.equal(fwd(res, CYRUS_HOST_HEADER), null);
    assert.equal(fwd(res, "x-pathname"), "/dashboard/cyrus");
  });
  it("flag on, Cyrus host: marker set, studio rewritten, portal handed to Nxeon, internal tree 404 everywhere", async () => {
    const s = await run("https://cyrus.my/studio/p1", "cyrus.my", ON);
    assert.equal(fwd(s, CYRUS_HOST_HEADER), "1");
    assert.match(s.headers.get("x-middleware-rewrite") ?? "", /\/dashboard\/cyrus\/p1$/);
    const p = await run("https://cyrus.my/dashboard/billing", "cyrus.my", ON);
    assert.equal(p.headers.get("location"), "https://nxeon.cloud/dashboard/billing");
    assert.equal((await run("https://cyrus.my/admin", "cyrus.my", ON)).status, 404);
    assert.equal((await run("https://nxeon.cloud/cyrus-host/sign-in", "nxeon.cloud", ON)).status, 404);
    assert.equal((await run("https://nxeon.cloud/cyrus-host/sign-in", "nxeon.cloud", {})).status, 404);
  });
});
